CREATE TABLE IF NOT EXISTS policies (multisig TEXT PRIMARY KEY, owner TEXT NOT NULL, body TEXT NOT NULL, hash TEXT NOT NULL, nonce TEXT NOT NULL, signature TEXT NOT NULL, updated INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS verdicts (multisig TEXT NOT NULL, idx INTEGER NOT NULL, creator TEXT NOT NULL, verdict TEXT NOT NULL, reasons TEXT NOT NULL, sol_out TEXT NOT NULL, tokens_out TEXT NOT NULL, at INTEGER NOT NULL, PRIMARY KEY (multisig, idx));
CREATE INDEX IF NOT EXISTS verdicts_at ON verdicts (at);
CREATE TABLE IF NOT EXISTS usage (multisig TEXT NOT NULL, day TEXT NOT NULL, n INTEGER NOT NULL, PRIMARY KEY (multisig, day));
CREATE TABLE IF NOT EXISTS counts (verdict TEXT PRIMARY KEY, n INTEGER NOT NULL);
